 "content": "def transform(grid):
    """Restore the grid's cyclic value pattern from the intact cells."""
    h = len(grid)
    w = len(grid[0]) if h else 0
    if not h or not w:
        return []
    # Recover horizontal step and row-to-row step by robustly scoring all
    # cyclic affine patterns. ARC pattern here is a repeated 1..9 sequence;
    # values may be corrupted to zero or duplicated locally.
    best = None
    best_score = -1
    for base in range(9):
        for dr in range(9):
            for dc in range(9):
                score = 0
                for r in range(h):
                    for c in range(w):
                        v = grid[r][c]
                        if v and v == ((base + r*dr + c*dc) % 9) + 1:
                            score += 1
                if score > best_score:
                    best_score, best = score, (base, dr, dc)
    base, dr, dc = best
    return [[((base + r*dr + c*dc) % 9) + 1 for c in range(w)] for r in range(h)]
